\label{thm:phase}
Assume \eqref{ass:K} and \eqref{eq:data}. For every $0\le\beta<\infty$, there exists a positive continuous directional amplitude $a_\beta$ on $\overline{\mathbb S_+}$. Define the directional phase by
\[
 \xi_\beta(\theta)=\log a_\beta(\theta).
\]
For every $0<B<\infty$, there exists $C_B>0$ such that
\begin{equation}\label{eq:holder-main}
 |a_\beta(\theta)-a_\beta(\omega)|
 \le C_B|\theta-\omega|^{1/3},
 \qquad 0\le\beta\le B,\quad\theta,\omega\in\overline{\mathbb S_+}.
\end{equation}
For every $0<\delta\le1$ and $0<Z<\infty$, the receiving front satisfies
\begin{equation}\label{eq:cone-wave}
 \sup_{\theta\in\Gamma_\delta,\ |z|\le Z}
 \left|u_+(t,(m(t)+z)\theta)-U_*(z-\xi_\beta(\theta))\right|\longrightarrow0
 \qquad(t\to\infty).
\end{equation}
Along the interface, both traces converge to the same profile:
\begin{equation}\label{eq:eq-wave}
 \sup_{\eta\in\mathbb S^{N-2},\ |z|\le Z}
 \left|u_\pm(t,(m(t)+z)\eta,0)-U_*(z-\xi_\beta(\eta,0))\right|\longrightarrow0
 \qquad(t\to\infty).
\end{equation}
This equatorial convergence also holds in bounded physical neighborhoods transverse to each equatorial ray. Both convergence statements are uniform for $\beta\in[0,B]$, for every finite $B>0$.

For $R>0$, $\theta\in\overline{\mathbb S_+}$, and a threshold $\upsilon\in(0,1)$, define the first arrival time on the receiving side by
\[
 T_\upsilon^\beta(R,\theta)=\inf\{t>0:u_+(t,R\theta)\ge\upsilon\},
\]
where the receiving trace is used when $\theta_N=0$. Then
\begin{equation}\label{eq:arrival}
 T_\upsilon^\beta(R,\theta)-T_\upsilon^0(R,\theta)\longrightarrow
 \tau_\beta(\theta):=\frac12\log\frac{a_0(\theta)}{a_\beta(\theta)}
 \qquad(R\to\infty).
\end{equation}
The limiting arrival-time difference is independent of $\upsilon$. The convergence is uniform for $\beta\in[0,B]$, for $\upsilon$ in compact subsets of $(0,1)$, and for directions in each fixed $\Gamma_\delta$, or separately on the equator.

\label{thm:parameters}
For every $0<B<\infty$, the directional amplitude $a_\beta(\theta)$, phase $\xi_\beta(\theta)$, and arrival-time difference $\tau_\beta(\theta)$ are jointly continuous in $(\beta,\theta)$ on $[0,B]\times\overline{\mathbb S_+}$. If \eqref{ass:C} also holds, then for every fixed pair $0\le\beta_1<\beta_2<\infty$,
\begin{equation}\label{eq:strict-gap}
 \inf_{\theta\in\overline{\mathbb S_+}}\bigl(a_{\beta_1}(\theta)-a_{\beta_2}(\theta)\bigr)>0,
 \qquad
 \inf_{\theta\in\overline{\mathbb S_+}}\bigl(\tau_{\beta_2}(\theta)-\tau_{\beta_1}(\theta)\bigr)>0.
\end{equation}

\label{thm:strong}
The function $I_N$ is positive and continuous on $\mathbb S_+$. For every $0<\delta\le1$, as $\beta\to\infty$,
\begin{align}
 a_\beta(\theta)&=2c_N I_N(\theta)\frac{\log\beta}{\beta}(1+o(1)),\label{eq:strong-a}\\
 \tau_\beta(\theta)&=\frac12\log\beta-\frac12\log\log\beta+C_N(\theta)+o(1),\label{eq:strong-tau}
\end{align}
uniformly for $\theta\in\Gamma_\delta$, where
\[
 C_N(\theta)=\frac12\log\frac{(4\pi)^{N/2}a_0(\theta)}{2I_N(\theta)}.
\]

\label{thm:grazing}
For $\eta\in\mathbb S^{N-2}$ and $0<s<1$, set
\[
 \theta_s=(\sqrt{1-s^2}\,\eta,s).
\]
As $s\downarrow0$,
\begin{equation}\label{eq:grazing-I}
 I_N(\theta_s)=4(4\pi)^{(N-2)/2}a_\mathrm{Neu}(\eta,0)\log(1/s)(1+o(1)),
\end{equation}
and consequently
\begin{equation}\label{eq:grazing-C}
 C_N(\theta_s)=-\frac12\log\log(1/s)
       +\frac12\log\frac{\pi a_0(\eta,0)}{2a_\mathrm{Neu}(\eta,0)}+o(1).
\end{equation}
Both asymptotic formulas hold uniformly for $\eta\in\mathbb S^{N-2}$.

\label{thm:saturation}
As $\beta\to\infty$, uniformly for $\eta\in\mathbb S^{N-2}$,
\begin{equation}\label{eq:saturation}
\begin{aligned}
 a_\beta(\eta,0)&\longrightarrow\frac12a_\mathrm{Neu}(\eta,0),\\
 \tau_\beta(\eta,0)&\longrightarrow
 \tau_*^{\rm eq}(\eta):=\frac12\log\frac{2a_0(\eta,0)}{a_\mathrm{Neu}(\eta,0)}.
\end{aligned}
\end{equation}
If \eqref{ass:C} also holds, then $\tau_\beta(\eta,0)$ increases strictly to this limit as $\beta$ increases, and
\begin{equation}\label{eq:saturation-range}
 0<\tau_*^{\rm eq}(\eta)<\frac12\log2.
\end{equation}
In particular, for each fixed $\eta\in\mathbb S^{N-2}$, with $\theta_s$ as above,
\begin{align*}
 \lim_{s\downarrow0}\lim_{\beta\to\infty}a_\beta(\theta_s)&=0,
 &\lim_{\beta\to\infty}\lim_{s\downarrow0}a_\beta(\theta_s)&=\tfrac12a_\mathrm{Neu}(\eta,0),\\
 \lim_{s\downarrow0}\lim_{\beta\to\infty}\tau_\beta(\theta_s)&=+\infty,
 &\lim_{\beta\to\infty}\lim_{s\downarrow0}\tau_\beta(\theta_s)&=\tau_*^{\rm eq}(\eta).
\end{align*}

\label{lem:energytrace}
Fix $0<B<\infty$ and an integer $M>(N+1)/2$. There exist $T_0\ge2$ and $C_{B,M}>0$ such that, for every $T\ge T_0$, $0<\beta\le B$, and $\eta\in\mathbb S^{N-2}$,
\begin{equation}\label{eq:trace-energy}
 \int_{\log T}^{\log(2T)}\int_{\rho\ge2a(t),\ v\in\mathbb R^{N-2}}
 (1+\rho^2+|v|^2)^M W(\tau,\rho,v,0)^2\,\mathrm d\rho\,\mathrm d v\,\mathrm d\tau
 \le C_{B,M}T^{-1/2},\qquad t=\mathrm e^\tau.
\end{equation}
Consequently,
\begin{equation}\label{eq:trace-L1}
 \int_{\log T}^{\log(2T)}\int_{\rho\ge2a(t),\ v\in\mathbb R^{N-2}}
 (1+\rho)W(\tau,\rho,v,0)\,\mathrm d\rho\,\mathrm d v\,\mathrm d\tau
 \le C_{B,M}T^{-1/4}.
\end{equation}
At $\beta=0$, the boundary trace of $W$ vanishes, so both estimates hold trivially.

\label{lem:wave-tails}
There exist $B_->0$ and $B_+\in\mathbb R$ such that, as $s\to-\infty$,
\begin{align*}
 1-U_*(s)&=B_-\mathrm e^{\lambda_*s}+O(\mathrm e^{2\lambda_*s}),\\
 U_*'(s)&=-\lambda_*B_-\mathrm e^{\lambda_*s}+O(\mathrm e^{2\lambda_*s}),\\
 U_*''(s)&=-\lambda_*^2B_-\mathrm e^{\lambda_*s}+O(\mathrm e^{2\lambda_*s}).
\end{align*}
As $s\to+\infty$,
\begin{align*}
 U_*(s)&=(s+B_+)\mathrm e^{-s}+O((1+s)^2\mathrm e^{-2s}),\\
 U_*'(s)&=(1-s-B_+)\mathrm e^{-s}+O((1+s)^2\mathrm e^{-2s}),\\
 U_*''(s)&=(s+B_+-2)\mathrm e^{-s}+O((1+s)^2\mathrm e^{-2s}).
\end{align*}
In particular, $r_U$ is well defined and
\begin{equation}\label{eq:wave-ratio}
 \|r_U\|_\infty<\infty,\qquad
 r_U(s)\longrightarrow\lambda_*\quad(s\to-\infty),\qquad
 r_U(s)=-1+\frac1s+O(s^{-2})\quad(s\to+\infty).
\end{equation}

\label{lem:localization}
For every $0<B<\infty$,
\begin{align*}
 \lim_{A\to\infty}\liminf_{t\to\infty}
 \inf_{\substack{0\le\beta\le B\\|x|\le m(t)-A}}
 u^\beta(t,x)&=1,\\
 \lim_{A\to\infty}\limsup_{t\to\infty}
 \sup_{\substack{0\le\beta\le B\\|x|\ge m(t)+A}}
 u^\beta(t,x)&=0.
\end{align*}
Both interface traces are included.

\label{lem:persistence}
Let $V\ge0$ be a whole-space supersolution satisfying
\[
 V_t\ge\Delta V+(1-Q)V,
 \qquad 0\le Q\le C.
\]
Assume that, for some $0<\sigma<1/4$, the potential $Q$ is bounded by a fixed multiple of the right-hand side of \eqref{eq:envelope} in $|x|\ge m(t)$. If $V$ dominates a nonzero, nonnegative compactly supported seed at some positive time, then there exists $c>0$ such that, for every compact $K\subset(0,\infty)$,
\begin{equation}\label{eq:persistence}
 \liminf_{t\to\infty}
 \inf_{\theta\in\mathbb S^{N-1},\ \rho\in K}
 \left[
 t^{-1/2}\mathrm e^{\rho\sqrt t}
 V\bigl(t,(m(t)+\rho\sqrt t)\theta\bigr)
 -c\rho\mathrm e^{-\rho^2/4}
 \right]\ge0.
\end{equation}
The constant $c$ can be chosen independently of $K$.

\label{lem:logistic-seed}
Consider the auxiliary reaction $f_{\log}(s)=s-s^2$. Let $0\le\varphi\in C_c^\infty(\mathbb R^N)$ be nonzero, and let $a_{\varepsilon,\varphi}$ denote the homogeneous directional amplitude for initial density $\varepsilon\varphi$. Then
\begin{equation}\label{eq:small-seed}
 \liminf_{\varepsilon\downarrow0}
 \inf_{\theta\in\mathbb S^{N-1}}
 \left[
 \frac{a_{\varepsilon,\varphi}(\theta)}
      {\varepsilon\log(1/\varepsilon)}
 -c_N\int_{\mathbb R^N}\mathrm e^{\theta\cdot y}\varphi(y)\,\mathrm d y
 \right]\ge0.
\end{equation}

\label{prop:lower}
On each fixed receiving cone,
\[
 \liminf_{\varepsilon\downarrow0}
 \inf_{\theta\in\Gamma_\delta}
 \left[
 \frac{a_{1/\varepsilon}(\theta)}{\varepsilon L}
 -2c_N I_N(\theta)
 \right]\ge0.
\]

\label{lem:early}
Fix $\gamma_0>0$ and $0<\eta_0<\gamma_0/[2(N+2)]$. If $T=\varepsilon^{-\eta_0}$, then, uniformly on $\Gamma_\delta$,
\begin{equation}\label{eq:early}
 M_\varepsilon(T)=o(\varepsilon),\qquad
 \int_T^\infty B_\varepsilon(t)\,\mathrm d t=o(\varepsilon).
\end{equation}

\label{prop:upper}
On each fixed receiving cone,
\[
 \limsup_{\varepsilon\downarrow0}
 \sup_{\theta\in\Gamma_\delta}
 \left[
 \frac{a_{1/\varepsilon}(\theta)}{\varepsilon L}
 -2c_N I_N(\theta)
 \right]\le0.
\]

\label{lem:tangential}
For each fixed $M<\infty$, as $t\to\infty$,
\begin{equation}\label{eq:tangent-tail}
 t\mathrm e^{2\lambda t}F_b(t,\eta)\longrightarrow
 A_N(\eta):=2(4\pi)^{(N-2)/2}a_\mathrm{Neu}(\eta,0)
\end{equation}
uniformly in $\eta$ and $0\le\lambda t\le M$.
Moreover, for $b$ sufficiently close to $1$ and $t\ge2$,
\begin{equation}\label{eq:tangent-bound}
 F_b(t,\eta)\le
 C\mathrm e^{-2\lambda t}t^{-1+k\lambda},
\end{equation}
with $C$ independent of $b,t,\eta$.

\label{rem:scope}
For each fixed $\beta>1$, continuity of $a_\beta$ on the closed receiving hemisphere makes $\beta a_\beta(\theta)/\log\beta$ bounded. By contrast, the coefficient in \eqref{eq:grazing-coefficient} diverges as the direction approaches the equator. Thus the strong-resistance amplitude expansion cannot hold uniformly on the entire open receiving hemisphere.

The delay expansion is likewise nonuniform there. For fixed $\beta>1$, its proposed right-hand side tends to $-\infty$ as $s\downarrow0$, whereas $\tau_\beta$ has a finite continuous equatorial limit. Theorem~\ref{thm:grazing} describes the grazing behavior of the coefficient obtained after the strong-resistance limit. It does not provide a joint angle--resistance transition law.
